def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to separate build metadata
        parts = v.split('+')
        core = parts[0]

        # Split on '-' to separate pre-release
        if '-' in core:
            main_part, prerelease = core.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            main_part = core
            prerelease_parts = None

        # Parse MAJOR.MINOR.PATCH
        version_parts = main_part.split('.')
        major = int(version_parts[0])
        minor = int(version_parts[1])
        patch = int(version_parts[2])

        return (major, minor, patch, prerelease_parts)

    def prerelease_sort_key(prerelease_parts):
        # If no pre-release, it sorts after any pre-release
        # So we return a tuple that sorts after any pre-release
        if prerelease_parts is None:
            return (1,)  # Sorts after (0, ...)

        # Convert pre-release parts to sortable form
        result = [0]  # Prefix with 0 to sort before non-prerelease versions
        for part in prerelease_parts:
            if part.isdigit():
                result.append((0, int(part)))  # Numeric sorts before non-numeric
            else:
                result.append((1, part))  # Non-numeric
        return tuple(result)

    # Create list of (sort_key, original_index, version_string)
    indexed_versions = []
    for idx, v in enumerate(versions):
        major, minor, patch, prerelease_parts = parse_version(v)
        sort_key = (major, minor, patch, prerelease_sort_key(prerelease_parts))
        indexed_versions.append((sort_key, idx, v))

    # Sort by sort_key, then by original index for stability
    indexed_versions.sort(key=lambda x: (x[0], x[1]))

    # Return just the version strings
    return [v for _, _, v in indexed_versions]

